package com.example.takura.communications.application;
import com.fasterxml.jackson.databind.ObjectMapper;import java.sql.Timestamp;import java.time.Clock;import java.time.Duration;import java.util.List;import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.support.TransactionTemplate;
@Service public class OutboxWorker{
 private final JdbcTemplate jdbc;private final TransactionTemplate transactions;private final CommunicationPort port;private final ObjectMapper json;private final Clock clock;
 public OutboxWorker(JdbcTemplate jdbc,TransactionTemplate transactions,CommunicationPort port,ObjectMapper json,Clock clock){this.jdbc=jdbc;this.transactions=transactions;this.port=port;this.json=json;this.clock=clock;}
 public int runOnce(){List<Job> jobs=claim(20);for(Job j:jobs)deliver(j);return jobs.size();}
 List<Job> claim(int limit){return transactions.execute(status->jdbc.query("WITH ready AS (SELECT id FROM takura.notification_outbox WHERE (state='PENDING' OR (state='LEASED' AND lease_until<?)) AND next_attempt_at<=? ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT ?) UPDATE takura.notification_outbox o SET state='LEASED',lease_until=?,leased_by=? FROM ready WHERE o.id=ready.id RETURNING o.id,o.payload::text,o.attempts",(rs,n)->new Job((UUID)rs.getObject(1),rs.getString(2),rs.getInt(3)),Timestamp.from(clock.instant()),Timestamp.from(clock.instant()),limit,Timestamp.from(clock.instant().plus(Duration.ofMinutes(2))),"worker-"+UUID.randomUUID()));}
 void deliver(Job j){try{var node=json.readTree(j.payload());port.sendToTestSink(node.path("template").asText(),node.path("recipient").asText());transactions.executeWithoutResult(s->jdbc.update("UPDATE takura.notification_outbox SET state='DELIVERED',completed_at=?,lease_until=NULL,leased_by=NULL WHERE id=?",Timestamp.from(clock.instant()),j.id()));}catch(RuntimeException|java.io.IOException failure){int attempt=j.attempts()+1;long[] minutes={1,5,15,60,240};String state=attempt>=minutes.length?"FAILED_REQUIRES_REVIEW":"PENDING";long delay=minutes[Math.min(attempt-1,minutes.length-1)];transactions.executeWithoutResult(s->jdbc.update("UPDATE takura.notification_outbox SET state=?,attempts=?,next_attempt_at=?,lease_until=NULL,leased_by=NULL WHERE id=?",state,attempt,Timestamp.from(clock.instant().plus(Duration.ofMinutes(delay))),j.id()));}}
 record Job(UUID id,String payload,int attempts){}
}
